import { test, expect } from '@playwright/test';

test.describe('Account Lockout After Failed Login Attempts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should lock an account after 5 failed login attempts', async ({ page }) => {
    // Attempt 1
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword1');
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await loginButton.click();

    const errorMessage = page.getByText('Invalid credentials');
    await expect(errorMessage).toBeVisible();

    // Attempt 2
    await passwordInput.fill('wrongpassword2');
    await loginButton.click();
    await expect(errorMessage).toBeVisible();

    // Attempt 3
    await passwordInput.fill('wrongpassword3');
    await loginButton.click();
    await expect(errorMessage).toBeVisible();

    // Attempt 4
    await passwordInput.fill('wrongpassword4');
    await loginButton.click();
    await expect(errorMessage).toBeVisible();

    // Attempt 5 - Should trigger lockout
    await passwordInput.fill('wrongpassword5');
    await loginButton.click();

    const lockoutMessage = page.getByText('Account locked. Please contact support');
    await expect(lockoutMessage).toBeVisible();

    const resetLink = page.getByRole('link', { name: /reset password/i });
    await expect(resetLink).toBeVisible();

    const contactSupportButton = page.getByRole('button', { name: /contact support/i });
    await expect(contactSupportButton).toBeVisible();
  });

  test('should allow account access after successful password reset', async ({ page }) => {
    // Attempt 1 - Failed
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword1');
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await loginButton.click();

    const errorMessage = page.getByText('Invalid credentials');
    await expect(errorMessage).toBeVisible();

    // Attempt 2 - Failed
    await passwordInput.fill('wrongpassword2');
    await loginButton.click();
    await expect(errorMessage).toBeVisible();

    // Attempt 3 - Failed
    await passwordInput.fill('wrongpassword3');
    await loginButton.click();
    await expect(errorMessage).toBeVisible();

    // Attempt 4 - Failed
    await passwordInput.fill('wrongpassword4');
    await loginButton.click();
    await expect(errorMessage).toBeVisible();

    // Attempt 5 - Should trigger lockout
    await passwordInput.fill('wrongpassword5');
    await loginButton.click();

    const lockoutMessage = page.getByText('Account locked. Please contact support');
    await expect(lockoutMessage).toBeVisible();

    // Reset password
    const resetLink = page.getByRole('link', { name: /reset password/i });
    await resetLink.click();

    const resetEmailInput = page.getByLabel('Reset email');
    await resetEmailInput.fill('user@example.com');
    const resetTokenButton = page.getByRole('button', { name: /send reset link/i });
    await resetTokenButton.click();

    const resetSuccessMessage = page.getByText('Password reset link sent');
    await expect(resetSuccessMessage).toBeVisible();

    // Verify account is unlocked
    const loginButtonAfterReset = page.getByRole('button', { name: /sign in/i });
    await expect(loginButtonAfterReset).toBeVisible();

    // Attempt login with correct password
    await passwordInput.fill('correctpassword123');
    await loginButtonAfterReset.click();

    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();
  });
});
